using System.Text;
using PcTidy.Core;
using PcTidy.Core.Model;
using PcTidy.Features.DriveMove.Common;
using PcTidy.Features.DriveMove.PcFacts;
using PcTidy.Hosting;
using PcTidy.TestbedGen;
using Xunit;

namespace PcTidy.Features.DriveMove.Tests;

[CollectionDefinition("drivemove-testbed", DisableParallelization = true)]
public class DriveMoveTestbedCollection { }

/// <summary>
/// One fake PC per test under testbed\drivemove\, built with the real composition root in sandbox mode (real SafetyGuard,
/// Executor and Undo). Either generated by TestbedBuilder or a bare tree for a specific layout. Deleted afterwards.
/// </summary>
internal sealed class DriveMoveSandbox : IDisposable
{
    public static readonly string TestbedRoot = Path.Combine(FindCodeRoot(), "testbed", "drivemove");
    public static readonly DateTime Now = new(2026, 11, 10, 12, 0, 0, DateTimeKind.Utc);

    /// <summary>Thresholds for tiny fake files: everything counts, nothing is "too small".</summary>
    public static readonly DriveMoveThresholds Tiny = new()
    {
        MinFolderBytes = 1, MinSuggestionBytes = 1, MinCacheBytes = 1, FullFreeBytes = 0, FullFreeFraction = 0.15,
    };

    private readonly bool _generated;

    public DriveMoveSandbox(string name, SandboxProfile? profile = null, bool generate = false, Action<AppSettings>? configure = null)
    {
        Profile = profile ?? SandboxProfile.Default;
        Root = Path.Combine(TestbedRoot, $"{name}-{Guid.NewGuid().ToString("N")[..6]}");
        _generated = generate;
        if (generate) TestbedBuilder.Generate(Root, TestbedSize.Small, Profile, new TestbedOptions { AnchorUtc = Now });
        else
        {
            Directory.CreateDirectory(Root);
            // A bare fake PC: the drive folders and the user folders exist.
            var k0 = new SandboxKnownLocations(Root, Profile);
            foreach (var d in k0.FixedDrives) Directory.CreateDirectory(d);
            foreach (var f in new[] { k0.Downloads, k0.Videos, k0.Music, k0.Pictures, k0.Documents, k0.Desktop, k0.LocalAppData, k0.RoamingAppData, k0.WindowsDir, k0.ProgramFiles, k0.ProgramData })
                Directory.CreateDirectory(f);
            foreach (var c in k0.CloudRoots) Directory.CreateDirectory(c);
        }
        Host = PcTidyHost.CreateSandbox(Root, Profile, configure);
        K = (SandboxKnownLocations)Host.Locations;
    }

    public string Root { get; }
    public SandboxProfile Profile { get; }
    public PcTidyHost Host { get; }
    public SandboxKnownLocations K { get; }
    public string C => K.FixedDrives[0];
    public string D => K.FixedDrives.Count > 1 ? K.FixedDrives[1] : throw new InvalidOperationException("one-drive profile");

    public FixedDriveMoveEnvironment Pc { get; } = new();

    /// <summary>Drive sizes for the sandbox's drives (default: the SandboxSystemInfo values, 128 GB free of 512 GB).</summary>
    public ISystemInfo? System { get; set; }

    public ScanContext Context(DriveMoveThresholds? thresholds = null, IReadOnlyList<string>? roots = null, ISafetyGuard? guard = null, IKnownLocations? locations = null)
    {
        var c = Host.CreateScanContext(ScanDepth.Quick, roots);
        return new ScanContext
        {
            Locations = locations ?? c.Locations, Safety = guard ?? c.Safety, InUse = c.InUse, Settings = c.Settings, Walker = c.Walker,
            Depth = c.Depth, Roots = roots, System = System ?? c.System, RunningProcesses = new HashSet<string>(),
            Options = new Dictionary<string, object>
            {
                [DriveMoveOptions.Now] = Now,
                [DriveMoveOptions.Environment] = Pc,
                [DriveMoveOptions.Thresholds] = thresholds ?? Tiny,
            },
        };
    }

    public string Put(string path, string text, DateTime? writtenUtc = null) => Put(path, Encoding.UTF8.GetBytes(text), writtenUtc);

    public string Put(string path, byte[] bytes, DateTime? writtenUtc = null)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.WriteAllBytes(path, bytes);
        if (writtenUtc is { } w)
        {
            File.SetCreationTimeUtc(path, w);
            File.SetLastWriteTimeUtc(path, w);
        }
        return path;
    }

    public static byte[] Bytes(int length, int seed)
    {
        var b = new byte[length];
        new Random(seed).NextBytes(b);
        return b;
    }

    /// <summary>Drives with chosen sizes (same roots as the sandbox).</summary>
    public FakeSystemInfo Drives(params (long Total, long Free, DriveMedia Media)[] sizes)
    {
        var list = K.FixedDrives.Select((d, i) => new DriveDetails(d, i == 0 ? "System" : "Data",
            i < sizes.Length ? sizes[i].Media : DriveMedia.Ssd, i < sizes.Length ? sizes[i].Total : 512L << 30,
            i < sizes.Length ? sizes[i].Free : 128L << 30, i == 0)).ToList();
        var s = new FakeSystemInfo(list);
        System = s;
        return s;
    }

    /// <summary>A Steam game: appmanifest + install folder.</summary>
    public string SteamGame(string library, string appId, string name, string dir, long sizeOnDisk, long? lastPlayed, long lastUpdated)
    {
        var apps = Path.Combine(library, "steamapps");
        var played = lastPlayed is { } p ? $"\t\"LastPlayed\"\t\t\"{p}\"\n" : "";
        Put(Path.Combine(apps, $"appmanifest_{appId}.acf"),
            $"\"AppState\"\n{{\n\t\"appid\"\t\t\"{appId}\"\n\t\"name\"\t\t\"{name}\"\n\t\"StateFlags\"\t\t\"4\"\n\t\"installdir\"\t\t\"{dir}\"\n" +
            $"\t\"LastUpdated\"\t\t\"{lastUpdated}\"\n{played}\t\"SizeOnDisk\"\t\t\"{sizeOnDisk}\"\n}}\n");
        var install = Path.Combine(apps, "common", dir);
        Put(Path.Combine(install, dir + ".exe"), "x");
        return install;
    }

    public void Dispose()
    {
        Host.Dispose();
        try
        {
            if (_generated) TestbedBuilder.Delete(Root);
            else ForceDelete(Root);
        }
        catch { /* best effort: the testbed folder is disposable */ }
    }

    internal static void ForceDelete(string dir)
    {
        if (!Directory.Exists(dir)) return;
        // Junctions first, as links only (never through them).
        foreach (var d in Directory.EnumerateDirectories(dir, "*", new EnumerationOptions { RecurseSubdirectories = true, AttributesToSkip = 0 }).ToList())
            if (Directory.Exists(d) && (File.GetAttributes(d) & FileAttributes.ReparsePoint) != 0) Directory.Delete(d);
        foreach (var f in Directory.EnumerateFiles(dir, "*", SearchOption.AllDirectories)) File.SetAttributes(f, FileAttributes.Normal);
        Directory.Delete(dir, recursive: true);
    }

    private static string FindCodeRoot()
    {
        var d = new DirectoryInfo(AppContext.BaseDirectory);
        while (d != null && !File.Exists(Path.Combine(d.FullName, "PcTidy.sln"))) d = d.Parent;
        return d?.FullName ?? throw new InvalidOperationException("PcTidy.sln not found");
    }
}

/// <summary>Chosen drive sizes and media; everything else plain.</summary>
internal sealed class FakeSystemInfo(IReadOnlyList<DriveDetails> drives) : ISystemInfo
{
    public PcTidy.Core.Model.GpuVendor PrimaryGpu => PcTidy.Core.Model.GpuVendor.Unknown;
    public IReadOnlyList<string> GpuNames => Array.Empty<string>();
    public bool IsLaptop => false;
    public bool HasBattery => false;
    public bool IsAdmin => false;
    public int WindowsBuild => 26100;
    public bool RebootPending => false;
    public IReadOnlyList<DriveDetails> Drives { get; } = drives;
    public IReadOnlySet<string> RunningProcesses() => new HashSet<string>();
}
